1	import { dirname, resolve } from '@std/path';
2	import {
3	  explicitServicePort,
4	  parseReadmeQuickstartCommands,
5	  README_QUICKSTART_EXPECTED_COMMANDS,
6	  readmeQuickstartArgv,
7	  substituteReadmeQuickstartCommand,
8	} from '../../../domain/readme-quickstart.ts';
9	import { resolveResourceUrlsFromAppHost } from '../scaffold/generated-app-endpoint.ts';
10	import { runAspireCommand } from './aspire-walk.ts';
11	
12	const JSR_CLI_PREFIX = 'jsr:@netscript/cli@';
13	const SERVICE_RESOURCE = 'users';
14	const RECEIPT_TAIL_LENGTH = 4_000;
15	
16	interface ReadmeWalkState {
17	  readonly cwd: string;
18	  readonly nextIndex: number;
19	  readonly servicePort?: number;
20	  readonly servicePortSource?: string;
21	  readonly servicePortError?: string;
22	}
23	
24	interface ReadmeCommandReceipt {
25	  readonly argv: readonly string[];
26	  readonly cwd: string;
27	  readonly durationMs: number;
28	  readonly exitCode: number;
29	  readonly readmeLine: number;
30	  readonly sourceCommand: string;
31	  readonly stderrTail: string;
32	  readonly stdoutTail: string;
33	  readonly substitutions: {
34	    readonly port?: number;
35	    readonly version?: string;
36	  };
37	  readonly evidence?: {
38	    readonly error?: string;
39	    readonly servicePort?: number;
40	    readonly source?: string;
41	  };
42	  readonly timedOut: boolean;
43	}
44	
45	/** Execute one indexed root README Quickstart command and emit its child receipt. */
46	export async function executeReadmeQuickstartCommand(
47	  repoRoot: string,
48	  runRoot: string,
49	  appHost: string,
50	  index: number,
51	  cliSpecifier: string,
52	  statePath: string,
53	  timeoutMs: number,
54	): Promise<number> {
55	  const readme = await Deno.readTextFile(resolve(repoRoot, 'README.md'));
56	  const commands = parseReadmeQuickstartCommands(readme);
57	  assertExpectedCommands(commands.map((entry) => entry.command));
58	  const entry = commands[index];
59	  if (!entry) throw new Error(`README Quickstart command index ${index} does not exist.`);
60	
61	  const version = publishedVersion(cliSpecifier, entry.line);
62	  const state = index === 0
63	    ? await initializeState(runRoot, statePath)
64	    : await readState(statePath, entry.line);
65	  if (state.nextIndex !== index) {
66	    throw new Error(
67	      `README line ${entry.line} cannot run out of order: expected command index ` +
68	        `${state.nextIndex}, received ${index}.`,
69	    );
70	  }
71	
72	  if (
73	    entry.command.includes('<port>') && state.servicePort === undefined && state.servicePortError
74	  ) {
75	    throw new Error(
76	      `README line ${entry.line} cannot substitute <port>: ${state.servicePortError}.`,
77	    );
78	  }
79	  const substituted = substituteReadmeQuickstartCommand(
80	    entry.command,
81	    { version, port: state.servicePort },
82	    entry.line,
83	  );
84	  const argv = readmeQuickstartArgv(substituted, entry.line);
85	  const started = performance.now();
86	  const result = argv[0] === 'cd'
87	    ? await changeDirectory(argv, state.cwd, entry.line)
88	    : await runCommand(argv, state.cwd, timeoutMs);
89	  const durationMs = Math.round(performance.now() - started);
90	  let nextState: ReadmeWalkState = state;
91	  if (result.code === 0 && !result.timedOut) {
92	    nextState = {
93	      ...state,
94	      cwd: argv[0] === 'cd' ? resolve(state.cwd, argv[1]) : state.cwd,
95	      nextIndex: index + 1,
96	    };
97	    if (entry.command.startsWith('aspire wait ')) {
98	      nextState = await captureServicePort(nextState, appHost);
99	    }
100	    await writeState(statePath, nextState);
101	  }
102	
103	  const receipt: ReadmeCommandReceipt = Object.freeze({
104	    argv,
105	    cwd: state.cwd,
106	    durationMs,
107	    exitCode: result.code,
108	    readmeLine: entry.line,
109	    sourceCommand: entry.command,
110	    stderrTail: tail(result.stderr),
111	    stdoutTail: tail(result.stdout),
112	    substitutions: Object.freeze({
113	      ...(entry.command.includes('<version>') ? { version } : {}),
114	      ...(entry.command.includes('<port>') && state.servicePort !== undefined
115	        ? { port: state.servicePort }
116	        : {}),
117	    }),
118	    ...(entry.command.startsWith('aspire wait ') &&
119	        (nextState.servicePort !== undefined || nextState.servicePortError !== undefined)
120	      ? {
121	        evidence: {
122	          ...(nextState.servicePort === undefined ? {} : { servicePort: nextState.servicePort }),
123	          ...(nextState.servicePortSource === undefined
124	            ? {}
125	            : { source: nextState.servicePortSource }),
126	          ...(nextState.servicePortError === undefined
127	            ? {}
128	            : { error: nextState.servicePortError }),
129	        },
130	      }
131	      : {}),
132	    timedOut: result.timedOut,
133	  });
134	  await writeReceipt(statePath, index, receipt);
135	  console.info(JSON.stringify(receipt));
136	  if (result.code !== 0 || result.timedOut) {
137	    console.error(
138	      `README line ${entry.line} failed exactly as printed: ${entry.command}`,
139	    );
140	  }
141	  return result.code;
142	}
143	
144	async function runCommand(
145	  argv: readonly string[],
146	  cwd: string,
147	  timeoutMs: number,
148	): Promise<{ code: number; stdout: string; stderr: string; timedOut: boolean }> {
149	  try {
150	    return await runAspireCommand(argv, cwd, timeoutMs);
151	  } catch (error) {
152	    return {
153	      code: 1,
154	      stdout: '',
155	      stderr: `Command could not start: ${errorMessage(error)}`,
156	      timedOut: false,
157	    };
158	  }
159	}
160	
161	async function initializeState(runRoot: string, statePath: string): Promise<ReadmeWalkState> {
162	  await Deno.mkdir(runRoot, { recursive: true });
163	  try {
164	    await Deno.remove(resolve(dirname(statePath), 'receipts'), { recursive: true });
165	  } catch (error) {
166	    if (!(error instanceof Deno.errors.NotFound)) throw error;
167	  }
168	  return Object.freeze({ cwd: runRoot, nextIndex: 0 });
169	}
170	
171	function assertExpectedCommands(actual: readonly string[]): void {
172	  if (actual.length !== README_QUICKSTART_EXPECTED_COMMANDS.length) {
173	    throw new Error(
174	      `README Quickstart contains ${actual.length} commands; ` +
175	        `readme.quickstart expects ${README_QUICKSTART_EXPECTED_COMMANDS.length}.`,
176	    );
177	  }
178	  for (let index = 0; index < actual.length; index++) {
179	    if (actual[index] !== README_QUICKSTART_EXPECTED_COMMANDS[index]) {
180	      throw new Error(
181	        `README Quickstart command ${index + 1} diverged: expected ` +
182	          `${JSON.stringify(README_QUICKSTART_EXPECTED_COMMANDS[index])}, received ` +
183	          `${JSON.stringify(actual[index])}.`,
184	      );
185	    }
186	  }
187	}
188	
189	function publishedVersion(specifier: string, line: number): string {
190	  if (!specifier.startsWith(JSR_CLI_PREFIX)) {
191	    throw new Error(
192	      `README line ${line} requires --source jsr and --cli ${JSR_CLI_PREFIX}<version>.`,
193	    );
194	  }
195	  const version = specifier.slice(JSR_CLI_PREFIX.length);
196	  if (!version || /\s/.test(version)) {
197	    throw new Error(`README line ${line} received an invalid published CLI version.`);
198	  }
199	  return version;
200	}
201	
202	async function changeDirectory(
203	  argv: readonly string[],
204	  cwd: string,
205	  line: number,
206	): Promise<{ code: number; stdout: string; stderr: string; timedOut: boolean }> {
207	  if (argv.length !== 2) {
208	    return {
209	      code: 2,
210	      stdout: '',
211	      stderr: `README line ${line} has an unsupported cd shape.`,
212	      timedOut: false,
213	    };
214	  }
215	  const target = resolve(cwd, argv[1]);
216	  try {
217	    const info = await Deno.stat(target);
218	    if (!info.isDirectory) throw new Error('target is not a directory');
219	    return { code: 0, stdout: '', stderr: '', timedOut: false };
220	  } catch (error) {
221	    return {
222	      code: 1,
223	      stdout: '',
224	      stderr: `README line ${line} cd ${argv[1]} failed: ${errorMessage(error)}`,
225	      timedOut: false,
226	    };
227	  }
228	}
229	
230	async function captureServicePort(
231	  state: ReadmeWalkState,
232	  appHost: string,
233	): Promise<ReadmeWalkState> {
234	  try {
235	    const urls = await resolveResourceUrlsFromAppHost(appHost, SERVICE_RESOURCE);
236	    const port = explicitServicePort(urls);
237	    return Object.freeze({
238	      ...state,
239	      servicePort: port,
240	      servicePortSource: `aspire describe ${SERVICE_RESOURCE} run receipt`,
241	    });
242	  } catch (error) {
243	    return Object.freeze({
244	      ...state,
245	      servicePortError: `service-port receipt failed: ${errorMessage(error)}`,
246	    });
247	  }
248	}
249	
250	async function readState(path: string, line: number): Promise<ReadmeWalkState> {
251	  let parsed: unknown;
252	  try {
253	    parsed = JSON.parse(await Deno.readTextFile(path));
254	  } catch (error) {
255	    throw new Error(`README line ${line} cannot read prior run receipt: ${errorMessage(error)}.`);
256	  }
257	  if (
258	    !isRecord(parsed) || typeof parsed.cwd !== 'string' ||
259	    typeof parsed.nextIndex !== 'number'
260	  ) {
261	    throw new Error(`README line ${line} found a malformed prior run receipt.`);
262	  }
263	  const servicePort = parsed.servicePort;
264	  const servicePortSource = parsed.servicePortSource;
265	  const servicePortError = parsed.servicePortError;
266	  if (servicePort !== undefined && typeof servicePort !== 'number') {
267	    throw new Error(`README line ${line} found a malformed service port receipt.`);
268	  }
269	  if (servicePortSource !== undefined && typeof servicePortSource !== 'string') {
270	    throw new Error(`README line ${line} found a malformed service port source.`);
271	  }
272	  if (servicePortError !== undefined && typeof servicePortError !== 'string') {
273	    throw new Error(`README line ${line} found a malformed service port error.`);
274	  }
275	  return Object.freeze({
276	    cwd: parsed.cwd,
277	    nextIndex: parsed.nextIndex,
278	    ...(servicePort === undefined ? {} : { servicePort }),
279	    ...(servicePortSource === undefined ? {} : { servicePortSource }),
280	    ...(servicePortError === undefined ? {} : { servicePortError }),
281	  });
282	}
283	
284	async function writeState(path: string, state: ReadmeWalkState): Promise<void> {
285	  await Deno.mkdir(dirname(path), { recursive: true });
286	  const temporary = `${path}.tmp`;
287	  await Deno.writeTextFile(temporary, `${JSON.stringify(state, null, 2)}\n`);
288	  await Deno.rename(temporary, path);
289	}
290	
291	async function writeReceipt(
292	  statePath: string,
293	  index: number,
294	  receipt: ReadmeCommandReceipt,
295	): Promise<void> {
296	  const path = resolve(
297	    dirname(statePath),
298	    'receipts',
299	    `${String(index + 1).padStart(2, '0')}.json`,
300	  );
301	  await Deno.mkdir(dirname(path), { recursive: true });
302	  await Deno.writeTextFile(path, `${JSON.stringify(receipt, null, 2)}\n`);
303	}
304	
305	function isRecord(value: unknown): value is Record<string, unknown> {
306	  return typeof value === 'object' && value !== null && !Array.isArray(value);
307	}
308	
309	function errorMessage(error: unknown): string {
310	  return error instanceof Error ? error.message : String(error);
311	}
312	
313	function tail(text: string): string {
314	  return text.length > RECEIPT_TAIL_LENGTH ? text.slice(-RECEIPT_TAIL_LENGTH) : text;
315	}
316	
317	if (import.meta.main) {
318	  const [repoRoot, runRoot, appHost, rawIndex, cliSpecifier, statePath, rawTimeout] = Deno.args;
319	  const index = Number(rawIndex);
320	  const timeoutMs = Number(rawTimeout);
321	  if (
322	    !repoRoot || !runRoot || !appHost || !Number.isSafeInteger(index) || !cliSpecifier ||
323	    !statePath ||
324	    !Number.isSafeInteger(timeoutMs) || timeoutMs <= 0
325	  ) {
326	    throw new Error(
327	      'repo root, run root, AppHost, command index, CLI specifier, state path, and timeout are required',
328	    );
329	  }
330	  try {
331	    Deno.exitCode = await executeReadmeQuickstartCommand(
332	      repoRoot,
333	      runRoot,
334	      appHost,
335	      index,
336	      cliSpecifier,
337	      statePath,
338	      timeoutMs,
339	    );
340	  } catch (error) {
341	    console.error(errorMessage(error));
342	    Deno.exitCode = 1;
343	  }
344	}
