2	import { createReadmeQuickstartSuite } from '../../suites/quickstart/readme-quickstart-suite.ts';
3	import { GATE, QUICKSTART } from '../../src/domain/cli-surface.ts';
4	import { PACKAGE_SOURCE } from '../../src/domain/extension-axes.ts';
5	
6	const EXACT_CLI = 'jsr:@netscript/cli@0.0.7-canary.1';
7	
8	Deno.test('README Quickstart suite exposes eleven ordered no-retry command receipts', () => {
9	  const suite = createReadmeQuickstartSuite({
10	    repoRoot: '/repo',
11	    packageSource: PACKAGE_SOURCE.JSR,
12	    cliEntrypoint: EXACT_CLI,
13	  });
14	
15	  assertEquals(suite.id, QUICKSTART.README);
16	  assertEquals(suite.defaultOptions.projectName, 'my-app');
17	  assertEquals(suite.defaultOptions.smokeRoot, '/repo/.llm/tmp/cli-e2e');
18	  assertEquals(suite.gates.map((gate) => gate.id), [
19	    GATE.README_QUICKSTART_INSTALL,
20	    GATE.README_QUICKSTART_INIT,
21	    GATE.README_QUICKSTART_CD_ASPIRE,
22	    GATE.README_QUICKSTART_ASPIRE_RESTORE,
23	    GATE.README_QUICKSTART_ASPIRE_START,
24	    GATE.README_QUICKSTART_ASPIRE_WAIT,
25	    GATE.README_QUICKSTART_CD_ROOT,
26	    GATE.README_QUICKSTART_DB_INIT,
27	    GATE.README_QUICKSTART_DB_GENERATE,
28	    GATE.README_QUICKSTART_DB_SEED,
29	    GATE.README_QUICKSTART_CURL_HEALTH,
30	    GATE.CLEANUP_ASPIRE_STOP,
31	  ]);
32	  for (const gate of suite.gates) {
33	    if (gate.kind === 'command') assertEquals(gate.retry, undefined, gate.id);
34	  }
35	});
36	
37	Deno.test('README Quickstart gates dispatch one indexed runtime-edge command each', () => {
38	  const suite = createReadmeQuickstartSuite({
39	    repoRoot: '/repo',
40	    packageSource: PACKAGE_SOURCE.JSR,
41	    cliEntrypoint: EXACT_CLI,
42	  });
43	  const context = {
44	    request: { suiteId: QUICKSTART.README, options: suite.defaultOptions },
45	    project: {
46	      repoRoot: '/repo',
47	      cliEntrypoint: EXACT_CLI,
48	      smokeRoot: '/repo',
49	      projectName: 'my-app',
50	      projectRoot: '/repo/my-app',
51	      appHost: '/repo/my-app/aspire/apphost.mts',
52	    },
53	  } as const;
54	
55	  const commands = suite.gates.slice(0, 11).map((gate) => {
56	    if (gate.kind !== 'command') throw new Error(`${gate.id} is not a command gate`);
57	    return gate.command(context);
58	  });
59	  assertEquals(commands.map((command) => command.at(-7)), Array(11).fill('/repo'));
60	  assertEquals(commands.map((command) => command.at(-6)), Array(11).fill('/repo'));
61	  assertEquals(
62	    commands.map((command) => command.at(-5)),
63	    Array(11).fill('/repo/my-app/aspire/apphost.mts'),
64	  );
65	  assertEquals(commands.map((command) => command.at(-4)), [...Array(11).keys()].map(String));
66	  assertEquals(commands.every((command) => command.includes('--allow-run')), true);
67	});
68	
69	Deno.test('README Quickstart command, gate-id, and phase tuples stay aligned', () => {
70	  const suite = createReadmeQuickstartSuite({ repoRoot: '/repo' });
71	  const commandGates = suite.gates.slice(0, -1);
72	  assertEquals(commandGates.length, 11);
73	  assertEquals(commandGates.every((gate) => gate.id.startsWith('readme.quickstart.')), true);
74	  assertEquals(commandGates.every((gate) => gate.phase !== undefined), true);
