              });
            }
          }
        }

        const failed = steps.filter((step) => step.verdict === 'failed').length;
        const report: RunReport = {
          ok: failed === 0,
          suiteId: suite.id,
          projectRoot: project.projectRoot,
          startedAt: startedAt.toISOString(),
          durationMs: Math.round(options.clock.monotonicMs() - startedMs),
